def process(batch, state):
    for event_id, account, amount in batch:
        state["balances"][account] = state["balances"].get(account, 0) + amount
    return state

exercises.tests:
state = {"balances": {}, "seen": set()}
b1 = [("e1", "amina", 50), ("e2", "tomas", 20), ("e3", "amina", 25)]
process(b1, state)
assert state["balances"] == {"amina": 75, "tomas": 20}
process(b1, state)                         # the whole batch redelivered after a crash
assert state["balances"] == {"amina": 75, "tomas": 20}
b2 = [("e3", "amina", 25), ("e4", "tomas", 5), ("e4", "tomas", 5), ("e5", "li", 10)]
process(b2, state)                         # overlaps b1, and repeats e4 inside itself
assert state["balances"] == {"amina": 75, "tomas": 25, "li": 10}
assert state["seen"] == {"e1", "e2", "e3", "e4", "e5"}
assert process([], state) is state

exercises.reference:
def process(batch, state):
    for event_id, account, amount in batch:
        if event_id in state["seen"]:
            continue
        state["balances"][account] = state["balances"].get(account, 0) + amount
        state["seen"].add(event_id)
    return state
